(function(){
'use strict';
const service=window.DRSXData.create();
const app=document.getElementById('app');
const audio=document.getElementById('audio-engine');
const state={user:null,current:null,isPlaying:false,genre:'Tous',query:'',directoryQuery:'',conversationId:'',modal:null,routeToken:0,notifications:[],loading:false,liveUnsubscribe:null};
const icons={home:'⌂',explore:'◈',heart:'♥',library:'▤',message:'◫',users:'◎',artist:'♬',announce:'⚑',stats:'▥',settings:'⚙',bell:'●',play:'▶',pause:'Ⅱ',prev:'◀',next:'▶',search:'⌕',arrow:'→',music:'♪',reserve:'◇',headphones:'◉',calendar:'▣',file:'▧',shield:'◆',more:'•••',send:'➤',download:'⇩',upload:'⇧',palette:'✦',edit:'✎',trash:'×',check:'✓',admin:'♛',clock:'◷',lock:'◆',drive:'△',plus:'＋'};
const icon=n=>icons[n]||'•';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>new Intl.NumberFormat('fr-FR',{notation:'compact',maximumFractionDigits:1}).format(Number(n)||0);
const money=n=>n==null?'Sur discussion':`${Number(n).toLocaleString('fr-FR')} €`;
const dateShort=d=>new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(d));
const timeAgo=d=>{const s=Math.max(1,Math.floor((Date.now()-new Date(d))/1000));if(s<60)return'il y a quelques secondes';if(s<3600)return`il y a ${Math.floor(s/60)} min`;if(s<86400)return`il y a ${Math.floor(s/3600)} h`;return`il y a ${Math.floor(s/86400)} j`;};
const wave=(count=38)=>Array.from({length:count},(_,i)=>`<i style="height:${12+(i*17)%36}px"></i>`).join('');
function activateSubscription(){if(state.liveUnsubscribe){try{state.liveUnsubscribe();}catch{}state.liveUnsubscribe=null;}if(state.user&&service.subscribe)state.liveUnsubscribe=service.subscribe(state.user,(type,row)=>{if(type==='notification'){toast(row.title||'Nouvelle notification');state.notifications.unshift(row);}if(type==='message'&&state.conversationId&&row.conversation_id===state.conversationId)route();});}
function toast(msg,type='ok'){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className=`toast ${type}`;t.textContent=msg;document.body.appendChild(t);setTimeout(()=>t.remove(),3000);}
function logo(){return `<a href="#/" class="logo"><span class="logo-mark">D</span><span class="logo-text">DanaTrap<small>RSX</small></span></a>`;}
function initials(name){return String(name||'DR').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();}
function profileAvatar(p,size=''){const style=p?.avatar?`background-image:url('${esc(p.avatar)}')`:'';return `<span class="avatar ${size}" style="${style}">${p?.avatar?'':esc(p?.initials||initials(p?.name))}</span>`;}
function sectionTitle(title,subtitle='',action=''){return `<div class="section-title"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>`;}
function statusClass(v){return v==='Publié'||v==='Acceptée'||v==='Validé'?'success':v==='Expiré'||v==='Refusée'?'danger':v==='Réservé'||v==='En discussion'?'warning':'';}
function themeVars(theme={}){return `--profile-accent:${theme.accent||'#f6c90e'};--profile-secondary:${theme.secondary||'#7c5cff'};--profile-bg:${theme.background||'#111217'};--profile-radius:${Number(theme.cardRadius)||24}px;--profile-border:${theme.cardBorder||'rgba(255,255,255,.13)'}`;}
function coverStyle(b){const d=b.design||{};const img=b.coverImage?`background-image:linear-gradient(rgba(0,0,0,.${Math.min(9,Math.round((d.overlay||45)/10))}),rgba(0,0,0,.${Math.min(9,Math.round((d.overlay||45)/10))})),url('${esc(b.coverImage)}');background-size:cover;background-position:center;`:'';return `${themeVars(d)};${img};font-family:${esc(d.titleFont||'Inter')}`;}
function playIcon(b){return b?.design?.customPlayIcon?`<img src="${esc(b.design.customPlayIcon)}" alt="">`:icon('play');}
function pauseIcon(b){return b?.design?.customPauseIcon?`<img src="${esc(b.design.customPauseIcon)}" alt="">`:icon('pause');}
function canEditBeat(b){return state.user&&(state.user.role==='Admin'||state.user.id===b.producer_id);}
function isCreator(){return state.user&&['Beatmaker','Admin'].includes(state.user.role);}
function isArtist(){return state.user&&['Artiste','Admin'].includes(state.user.role);}

function beatCard(b,{owner=false}={}){
 const expired=b.visibility==='Expiré';
 return `<article class="beat-card custom-beat-card ${expired?'expired':''}" style="${coverStyle(b)}">
  <div class="beat-cover ${b.coverClass||'cover-a'}" style="${b.coverImage?`background-image:url('${esc(b.coverImage)}');background-size:cover;background-position:center`:''}">
   <span class="cover-grid"></span><span class="status beat-status ${statusClass(b.visibility)}">${esc(b.visibility)}</span>
   <button class="beat-play" data-play="${b.id}" aria-label="Lire ${esc(b.title)}">${state.current?.id===b.id&&state.isPlaying?pauseIcon(b):playIcon(b)}</button><span class="beat-duration">${esc(b.duration||'0:00')}</span>
  </div>
  <div class="beat-card-body ${esc(b.design?.infoLayout||'bottom')}"><div class="beat-title-row"><div><a class="beat-title" href="#/beat/${b.slug||b.id}">${esc(b.title)}</a><a class="producer-link" href="#/profile/${b.producer_slug||b.producer_id}">${esc(b.producer_name)}</a></div><button class="icon-btn" data-menu-beat="${b.id}">${icon('more')}</button></div>
  <div class="chips"><span>${esc(b.bpm)} BPM</span><span>${esc(b.key)}</span><span>${esc(b.genre)}</span></div>
  <div class="beat-foot"><span>${icon('headphones')} ${fmt(b.plays)}</span><div class="card-actions">${owner||canEditBeat(b)?`<a class="btn subtle small" href="#/app/production/${b.id}/edit">${icon('edit')} Modifier</a>`:expired?'':`<a class="btn primary small" href="#/beat/${b.slug||b.id}">${icon('reserve')} Réserver</a>`}</div></div></div>
 </article>`;
}
function beatGrid(list,opts={}){return list.length?`<div class="beats-grid">${list.map(b=>beatCard(b,opts)).join('')}</div>`:`<div class="empty-state"><span>${icon('music')}</span><strong>Aucune production</strong><p>Aucun résultat ne correspond à cette sélection.</p></div>`;}
function profileCard(p){return `<article class="creator-card theme-frame ${esc(p.theme?.frameStyle||'glass')}" style="${themeVars(p.theme)}"><div class="creator-banner profile-effect ${esc(p.theme?.profileEffect||'none')}" style="${p.banner?`background-image:url('${esc(p.banner)}')`:''}"></div><div class="creator-card-main">${profileAvatar(p,'large')}<div><a href="#/profile/${p.slug}"><strong>${esc(p.name)} ${p.verified?'<span class="verified">✓</span>':''}</strong></a><span>${esc(p.username)} · ${esc(p.location||'Non renseigné')}</span></div></div><p>${esc(p.bio)}</p><div class="creator-stats"><span><strong>${fmt(p.followers)}</strong> abonnés</span><span><strong>${fmt(p.plays)}</strong> écoutes</span></div><a class="btn profile-btn" href="#/profile/${p.slug}">Voir le profil ${icon('arrow')}</a></article>`;}
function profileGrid(list){return list.length?`<div class="creator-grid">${list.map(profileCard).join('')}</div>`:`<div class="empty-state"><strong>Aucun profil trouvé</strong></div>`;}
function statCard(i,label,value,change){return `<div class="stat-card"><span class="stat-icon">${icon(i)}</span><div><span>${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(change)}</small></div></div>`;}

function landing(beats,makers,artists){return `<div class="landing"><header class="landing-nav">${logo()}<nav><a href="#beats">Productions</a><a href="#creators">Créateurs</a><a href="#how">Réservation</a></nav><div class="landing-actions"><a class="btn subtle" href="#/connexion">Connexion</a><a class="btn primary" href="#/inscription">Créer un compte</a></div></header><main><section class="hero"><span class="cover-grid"></span><div class="hero-copy"><span class="badge">✦ Une identité différente pour chaque créateur</span><h1>Réserve. Discute.<br><em>Crée ton morceau.</em></h1><p>Découvre une production, choisis une licence et ouvre automatiquement une conversation privée avec le beatmaker. Aucun paiement imposé : les deux créateurs décident ensemble.</p><div class="hero-actions"><a class="btn primary" href="#/explorer">Explorer les productions ${icon('arrow')}</a><a class="btn ghost" href="#/inscription">Créer mon univers</a></div><div class="hero-metrics"><div><strong>${makers.length}+</strong><span>${window.DRSXData.isDemo()?'Beatmakers démo':'Beatmakers'}</span></div><div><strong>${artists.length}+</strong><span>${window.DRSXData.isDemo()?'Artistes démo':'Artistes'}</span></div><div><strong>100%</strong><span>Réservation et discussion</span></div></div></div><div class="hero-visual"><span class="hero-orb"></span><div class="hero-card"><div class="hero-cover cover-a"><span class="cover-grid"></span><span class="floating-tag">Sélection RSX</span><button class="hero-play" data-play="${beats[0]?.id||''}">${playIcon(beats[0])}</button></div><div class="hero-card-info"><span class="eyebrow">Production mise en avant</span><h3>${esc(beats[0]?.title||'Nocturne')}</h3><p>${esc(beats[0]?.producer_name||'Dzl 971')} · ${esc(beats[0]?.bpm||142)} BPM · ${esc(beats[0]?.key||'B min')}</p><div class="waveform">${wave()}</div></div></div></div></section><section id="beats" class="landing-section"><div class="center-title"><span class="badge">Catalogue</span><h2>Des productions avec une vraie identité</h2><p>Chaque beatmaker peut personnaliser ses cartes, ses licences, ses boutons et son univers visuel.</p></div>${beatGrid(beats.slice(0,4))}</section><section id="how" class="landing-section feature-wrap"><div class="center-title"><span class="badge">Nouveau fonctionnement</span><h2>La réservation remplace le paiement direct</h2></div><div class="feature-grid">${[['◇','Choix de la licence','L’artiste sélectionne MP3, WAV, Premium, Exclusive ou une licence personnalisée.'],['◫','Conversation automatique','Une discussion privée est créée avec un bloc complet sur la production réservée.'],['✓','Décision entre créateurs','Le beatmaker accepte, refuse ou négocie, puis marque la production Expirée si elle est prise.'],['✦','Profils uniques','Couleurs, effets, cadres, arrière-plan, réseaux, polices et icônes personnalisées.'],['△','Stockage Drive','MP3, WAV, FLP, ZIP, stems et images sont envoyés vers ton Google Drive.'],['♛','Administration totale','Dzl 971 peut modifier, ajouter, retirer ou supprimer tous les contenus et comptes.']].map(x=>`<article class="feature-card"><span class="feature-icon">${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section id="creators" class="landing-section"><div class="center-title"><span class="badge">Communauté</span><h2>Beatmakers et artistes à découvrir</h2></div>${profileGrid([...makers.slice(0,2),...artists.slice(0,2)])}</section><section class="landing-section"><div class="cta"><div><span class="badge">DanaTrap RSX</span><h2>Construis une page qu’on reconnaît immédiatement.</h2><p>Ton profil, tes productions, tes effets et tes propres icônes.</p></div><a class="btn primary" href="#/inscription">Commencer gratuitement ${icon('arrow')}</a></div></section></main><footer class="landing-footer">${logo()}<p>© 2026 DanaTrap RSX — Réservation et collaboration musicale.</p></footer></div>`;}

function authPage(mode='login'){
 const login=mode==='login',demo=window.DRSXData.isDemo();
 const demoBox=demo?`<div class="demo-box"><strong>Comptes de démonstration</strong><span>Beatmaker : demo@danatrap.fr / DEMO1234</span><span>Artiste : artiste@danatrap.fr / ARTISTE1234</span><span>Administrateur Dzl 971 : admin@danatrap.fr / ADMIN1234</span></div>`:'';
 return `<div class="auth-page"><section class="auth-art"><div>${logo()}</div><div class="auth-quote"><span class="badge">DanaTrap RSX</span><blockquote>${login?'Retrouve tes réservations et tes conversations.':'Crée ton espace, puis personnalise-le sans limite.'}</blockquote><p>${demo?'Le site fonctionne actuellement en mode démonstration local.':'Tes comptes, réservations et conversations sont connectés à la plateforme en ligne.'}</p></div><small>Réservation · Messagerie · Drive · Personnalisation</small></section><section class="auth-panel"><a class="back-link" href="#/">← Retour à l’accueil</a><div class="auth-box"><h1>${login?'Bon retour parmi nous':'Créer mon compte'}</h1><p>${login?'Connecte-toi pour accéder à ton espace.':'Choisis ton rôle. Tu pourras modifier ton profil ensuite.'}</p><form id="${login?'login':'register'}-form" class="form">${login?'':`<label>Nom public<input name="name" required placeholder="Ton nom d’artiste"></label><label>Rôle<select name="role" required><option>Artiste</option><option>Beatmaker</option><option>Producteur</option><option>Ingénieur du son</option><option>Manager</option></select></label>`}<label>Adresse e-mail<input type="email" name="email" required value="${login&&demo?'demo@danatrap.fr':''}"></label><label>Mot de passe<input type="password" name="password" required minlength="8" value="${login&&demo?'DEMO1234':''}"></label>${login?'<p id="login-error" class="form-error hidden"></p>':''}<button class="btn primary full" type="submit">${login?'Se connecter':'Créer mon compte'}</button>${demoBox}</form><p class="auth-switch">${login?'Pas encore de compte ? <a href="#/inscription">Inscription</a>':'Déjà inscrit ? <a href="#/connexion">Connexion</a>'}</p></div></section></div>`;
}

function renderModal(){const m=state.modal;if(!m)return'';if(m.type==='reserve')return `<div class="modal-backdrop"><div class="modal-card"><button class="modal-close" data-close-modal>×</button><span class="badge">Réservation</span><h2>${esc(m.beat.title)}</h2><p>Licence choisie : <strong>${esc(m.license)}</strong></p><div class="reservation-mini"><span class="mini-cover ${m.beat.coverClass||'cover-a'}"></span><div><strong>${esc(m.beat.title)}</strong><span>${esc(m.beat.producer_name)} · ${m.beat.bpm} BPM · ${esc(m.beat.key)}</span></div></div><label>Message facultatif<textarea id="reservation-note" placeholder="Présente ton projet ou demande une modification..."></textarea></label><p class="modal-note">Après confirmation, le beatmaker reçoit une notification et une conversation est créée automatiquement.</p><button class="btn primary full" data-confirm-reservation>Confirmer la réservation</button></div></div>`;if(m.type==='announcement')return `<div class="modal-backdrop"><form id="announcement-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Publier une annonce</h2><label>Titre<input name="title" required></label><label>Besoin<textarea name="details" required></textarea></label><label>Budget indicatif<input name="budget" required placeholder="80–130 €"></label><label>Date limite<input name="deadline" required placeholder="31 août 2026"></label><button class="btn primary">Publier</button></form></div>`;if(m.type==='playlist')return `<div class="modal-backdrop"><form id="playlist-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Nouvelle playlist</h2><label>Nom<input name="name" required placeholder="Ex. Projet album"></label><button class="btn primary">Créer</button></form></div>`;if(m.type==='addUser')return `<div class="modal-backdrop"><form id="admin-add-user-form" class="modal-card"><button type="button" class="modal-close" data-close-modal>×</button><h2>Ajouter un utilisateur</h2><label>Nom<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Mot de passe<input name="password" value="DEMO1234" required></label><label>Rôle<select name="role"><option>Artiste</option><option>Beatmaker</option><option>Manager</option></select></label><button class="btn primary">Ajouter</button></form></div>`;return'';}

function loading(){return `<div class="loading-screen"><div class="loading-bars">${Array.from({length:7},(_,i)=>`<i style="height:${18+(i%4)*8}px"></i>`).join('')}</div><p>Chargement de DanaTrap RSX…</p></div>`;}
function notFound(){return state.user?appShell('Page introuvable','La route demandée n’existe pas.',`<div class="empty-state full-page"><strong>404</strong><p>Cette page n’existe pas ou a été déplacée.</p><a class="btn primary" href="#/app">Retour au tableau de bord</a></div>`):`<div class="empty-state full-page"><strong>404</strong><p>Cette page n’existe pas.</p><a class="btn primary" href="#/">Retour à l’accueil</a></div>`;}
function activeRoute(path){const raw=(location.hash||'#/app').slice(1);return path==='/app'?raw==='/app':raw===path||raw.startsWith(path+'/');}
function navItem(path,label,i){return `<a class="side-link ${activeRoute(path)?'active':''}" href="#${path}"><span>${icon(i)}</span>${esc(label)}</a>`;}
function mobileItem(path,label,i){return `<a class="${activeRoute(path)?'active':''}" href="#${path}"><span>${icon(i)}</span><small>${esc(label)}</small></a>`;}
function playerMarkup(){const b=state.current;if(!b)return `<div class="player player-empty"><span>${icon('music')}</span><p>Sélectionne une production pour lancer la préécoute.</p></div>`;return `<div class="player ${state.isPlaying?'is-playing':''}"><div class="player-track"><span class="mini-cover ${b.coverClass||'cover-a'}" style="${b.coverImage?`background-image:url('${esc(b.coverImage)}');background-size:cover`:''}"></span><div><strong>${esc(b.title)}</strong><span>${esc(b.producer_name)}</span></div></div><div class="player-center"><div class="player-controls"><button data-player="prev" aria-label="Précédent">${icon('prev')}</button><button class="player-toggle" data-player="toggle" aria-label="Lecture pause">${state.isPlaying?pauseIcon(b):playIcon(b)}</button><button data-player="next" aria-label="Suivant">${icon('next')}</button></div><div class="progress-row"><small id="current-time">0:00</small><input id="progress" type="range" min="0" max="100" value="0"><small id="duration">${esc(b.duration||'0:00')}</small></div></div><div class="player-extra"><button class="icon-btn" data-favorite="${b.id}">${icon('heart')}</button><span>${icon('headphones')}</span><input id="volume" class="volume" type="range" min="0" max="1" step=".05" value="${audio.volume||.75}"></div></div>`;}
function appShell(title,subtitle,content){const unread=(state.notifications||[]).filter(n=>!n.read).length;const creator=isCreator();return `<div class="app-shell"><aside class="sidebar">${logo()}<nav class="side-nav">${navItem('/app','Tableau de bord','home')}${navItem('/app/explorer','Explorer','explore')}${navItem('/app/beatmakers','Beatmakers','users')}${navItem('/app/artistes','Artistes','artist')}${navItem('/app/favoris','Favoris','heart')}${navItem('/app/playlists','Playlists','library')}${navItem('/app/messages','Messages','message')}${navItem('/app/reservations','Réservations','reserve')}${navItem('/app/collaborations','Collaborations','users')}${navItem('/app/annonces','Annonces','announce')}${creator?navItem('/app/productions','Mes productions','music'):''}${navItem('/app/personnalisation','Personnalisation','palette')}${navItem('/app/statistiques','Statistiques','stats')}${state.user?.role==='Admin'?navItem('/admin','Administration','admin'):''}</nav><div class="side-bottom">${navItem('/app/parametres','Paramètres','settings')}<button class="side-link" data-action="logout"><span>↪</span>Déconnexion</button></div></aside><header class="topbar"><div><span class="eyebrow">${esc(subtitle||'DanaTrap RSX')}</span><h1>${esc(title)}</h1></div><div class="top-actions"><a class="icon-btn notification-btn ${unread?'unread':''}" href="#/app/notifications" aria-label="Notifications">${icon('bell')}${unread?`<small>${unread}</small>`:''}</a><a class="user-pill" href="#/profile/${state.user?.id||''}">${profileAvatar(state.user,'small')}<div><strong>${esc(state.user?.name||'Compte')}</strong><small>${esc(state.user?.role||'Membre')}</small></div></a></div></header><main class="page-wrap">${content}</main>${playerMarkup()}<nav class="mobile-nav">${mobileItem('/app','Accueil','home')}${mobileItem('/app/explorer','Explorer','explore')}${mobileItem('/app/messages','Messages','message')}${mobileItem('/app/reservations','Réservations','reserve')}${mobileItem('/app/personnalisation','Profil','palette')}</nav>${renderModal()}</div>`;}
function publicShell(content){return `<div class="landing"><header class="landing-nav">${logo()}<nav><a href="#/explorer">Productions</a><a href="#/connexion">Connexion</a></nav><div class="landing-actions"><a class="btn subtle" href="#/connexion">Connexion</a><a class="btn primary" href="#/inscription">Créer un compte</a></div></header><main class="landing-section">${content}</main>${playerMarkup()}</div>${renderModal()}`;}
function profileById(list,id){return list.find(p=>p.user_id===id)||{name:'Utilisateur',initials:'UT',role:'Membre'};}
function selected(v,current){return String(v)===String(current)?'selected':'';}
function checked(v){return v?'checked':'';}

async function dashboard(){const [profile,beats,reservations,conversations,announcementsList,collabs]=await Promise.all([service.getProfile(state.user.id),service.listBeats(isCreator()?{producer_id:state.user.id}:{publicOnly:true}),service.listReservations(state.user),service.listConversations(state.user),service.announcements(),service.collaborations(state.user)]);const publicBeats=isCreator()?beats:beats.slice(0,4);const heroTitle=state.user.role==='Artiste'?'Trouve la prochaine identité de ton morceau.':'Fais vivre ton catalogue et réponds aux artistes.';const heroText=state.user.role==='Artiste'?'Réserve une licence, présente ton projet et discute directement avec le beatmaker.':'Suis les réservations, personnalise tes productions et gère les discussions depuis un seul espace.';const pending=reservations.filter(r=>!['Acceptée','Refusée'].includes(r.status)).length;const unread=(state.notifications||[]).filter(n=>!n.read).length;const body=`<div class="stack"><section class="dashboard-hero"><div><span class="badge">Bonjour ${esc(profile?.name||state.user.name)}</span><h2>${esc(heroTitle)}</h2><p>${esc(heroText)}</p><div class="hero-actions">${isCreator()?'<a class="btn primary" href="#/app/upload">Ajouter une production</a>':'<a class="btn primary" href="#/app/explorer">Explorer les productions</a>'}<a class="btn ghost" href="#/app/messages">Ouvrir les messages</a></div></div><div class="disc"><span>DRSX</span></div></section><section class="stats-grid">${statCard('headphones','Écoutes',fmt((profile?.plays||0)),'Activité totale')}${statCard('reserve','Réservations',String(reservations.length),`${pending} en cours`)}${statCard('message','Conversations',String(conversations.length),`${unread} notification(s)`)}${statCard('users','Collaborations',String(collabs.length),'Projets privés')}</section><section>${sectionTitle(isCreator()?'Tes productions récentes':'Productions recommandées','Préécoute, licences et réservation.',`<a class="text-link" href="#/app/${isCreator()?'productions':'explorer'}">Tout afficher →</a>`)}${beatGrid(publicBeats.slice(0,4),{owner:isCreator()})}</section><div class="two-columns"><section class="panel">${sectionTitle('Dernières conversations','Discussions créées après réservation.',`<a class="text-link" href="#/app/messages">Messages →</a>`)}${conversations.length?conversations.slice(0,4).map(c=>`<a class="project-row" href="#/app/messages/${c.id}">${profileAvatar((c.members_profiles||[]).find(p=>p.user_id!==state.user.id)||c.members_profiles?.[0],'small')}<div class="project-info"><strong>${esc(c.title)}</strong><span>${esc(c.last_message?.text||'Aucun message')}</span></div><div class="project-meta"><strong>${timeAgo(c.updated_at)}</strong><small>Ouvrir</small></div></a>`).join(''):'<div class="empty-state"><strong>Aucune conversation</strong><p>Une conversation apparaîtra après une réservation.</p></div>'}</section><section class="panel">${sectionTitle('Annonces récentes','Besoins publiés par la communauté.',`<a class="text-link" href="#/app/annonces">Voir tout →</a>`)}${announcementsList.slice(0,4).map(a=>`<div class="announcement-row"><span class="avatar small">${initials(a.author)}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.details)}</p><small>${esc(a.budget)} · ${esc(a.deadline)}</small></div></div>`).join('')}</section></div></div>`;return appShell('Tableau de bord','Vue générale',body);}

async function explore(publicView=false){const genres=['Tous','Trap','Drill','Afro','R&B','Dancehall','Pop urbaine'];const beats=await service.listBeats({publicOnly:true,genre:state.genre,query:state.query});const content=`<div class="stack"><section class="explore-hero"><div><span class="badge">Catalogue DanaTrap</span><h2>Explore les univers des beatmakers.</h2><p>Écoute les préversions, compare les licences puis réserve la production qui correspond à ton projet.</p></div><label class="search-box">${icon('search')}<input id="beat-search" value="${esc(state.query)}" placeholder="Titre, beatmaker, genre…"></label></section><section class="filters"><div class="genre-tabs">${genres.map(g=>`<button class="${state.genre===g?'active':''}" data-genre="${esc(g)}">${esc(g)}</button>`).join('')}</div><div class="filter-grid"><label>Humeur<select><option>Toutes</option><option>Sombre</option><option>Énergique</option><option>Mélancolique</option></select></label><label>BPM<select><option>Tous</option><option>80–110</option><option>111–140</option><option>141+</option></select></label><label>Licence<select><option>Toutes</option><option>MP3</option><option>WAV</option><option>Premium</option><option>Exclusive</option></select></label><label>Disponibilité<select><option>Publié et réservé</option><option>Publié uniquement</option></select></label></div></section><section>${sectionTitle(`${beats.length} production${beats.length>1?'s':''}`,'Résultats disponibles dans le catalogue.')}${beatGrid(beats)}</section></div>`;return publicView?publicShell(content):appShell('Explorer','Catalogue des productions',content);}

async function beatDetail(ref){const beat=await service.getBeat(ref);if(!beat)return notFound();const producer=await service.getProfile(beat.producer_id);const licenses=(beat.licenses||[]).filter(l=>l.active!==false);const available=beat.visibility!=='Expiré';const body=`<div class="detail-page custom-detail" style="${coverStyle(beat)}"><a class="detail-back btn subtle small" href="${state.user?'#/app/explorer':'#/explorer'}">← Retour au catalogue</a><section class="detail-hero"><div class="detail-cover ${beat.coverClass||'cover-a'}" style="${beat.coverImage?`background-image:url('${esc(beat.coverImage)}');background-size:cover;background-position:center`:''}"><span class="cover-grid"></span><button class="hero-play" data-play="${beat.id}">${state.current?.id===beat.id&&state.isPlaying?pauseIcon(beat):playIcon(beat)}</button><span class="status beat-status ${statusClass(beat.visibility)}">${esc(beat.visibility)}</span></div><div class="detail-info"><span class="eyebrow">${esc(beat.genre)} · ${esc(beat.mood)}</span><h2>${esc(beat.title)}</h2><a class="producer-line" href="#/profile/${producer?.slug||beat.producer_id}">${profileAvatar(producer,'small')}<div><strong>${esc(beat.producer_name)}</strong><small>${esc(producer?.role||'Beatmaker')} · ${esc(producer?.location||'')}</small></div></a><p>${esc(beat.description||'Aucune description renseignée.')}</p><div class="chips detail-chips"><span>${beat.bpm} BPM</span><span>${esc(beat.key)}</span>${(beat.tags||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div><div class="audio-preview"><button data-play="${beat.id}">${state.current?.id===beat.id&&state.isPlaying?pauseIcon(beat):playIcon(beat)}</button><div class="waveform">${wave(48)}</div><span>${esc(beat.duration||'0:00')}</span></div><div class="detail-actions"><button class="btn subtle" data-favorite="${beat.id}">${icon('heart')} Favori</button>${canEditBeat(beat)?`<a class="btn primary" href="#/app/production/${beat.id}/edit">Modifier la production</a>`:''}</div></div></section><section>${sectionTitle('Choisir une licence','La réservation ouvre une discussion, elle ne déclenche aucun paiement.')}${licenses.length?`<div class="license-grid">${licenses.map(l=>`<article class="license-card"><span class="eyebrow">Licence</span><h3>${esc(l.name)}</h3><strong class="beat-price">${money(l.price)}</strong><p>${esc(l.description)}</p><small>${esc(l.terms)}</small>${available?`<button class="btn primary full" data-reserve="${beat.id}" data-license="${esc(l.name)}">Réserver cette licence</button>`:'<button class="btn subtle full" disabled>Production expirée</button>'}</article>`).join('')}</div>`:'<div class="empty-state"><strong>Aucune licence active</strong></div>'}</section></div>`;return state.user?appShell(beat.title,'Détail de la production',body):publicShell(body);}

async function profilePage(ref){const profile=await service.getProfile(ref);if(!profile)return notFound();const beats=await service.listBeats({producer_id:profile.user_id,publicOnly:true});const t=profile.theme||{};const own=state.user&&(state.user.id===profile.user_id||state.user.role==='Admin');const socials=Object.entries(profile.socials||{}).filter(([,v])=>v);const body=`<div class="profile-universe effect-${esc(t.profileEffect||'none')} frame-${esc(t.frameStyle||'glass')}" style="${themeVars(t)};${t.backgroundImage?`--profile-bg-image:url('${esc(t.backgroundImage)}')`:''}"><div class="profile-ambient"></div><div class="profile-banner" style="${profile.banner?`background-image:url('${esc(profile.banner)}');background-size:cover;background-position:center`:''}"></div><section class="custom-profile-head">${profileAvatar(profile,'large')}<div class="profile-bio"><span class="eyebrow">${esc(profile.role)}</span><h1>${esc(profile.name)} ${profile.verified?'<span class="verified">✓</span>':''}</h1><span>${esc(profile.username)} · ${esc(profile.location||'Localisation non renseignée')}</span><p>${esc(profile.bio)}</p><div class="social-row">${socials.map(([k,v])=>`<span>${esc(k)} · ${esc(v)}</span>`).join('')}</div></div><div class="profile-actions">${own?'<a class="btn primary" href="#/app/personnalisation">Personnaliser ma page</a>':'<button class="btn profile-btn" data-toast="Profil suivi">Suivre</button>'}</div></section><div class="profile-grid"><section class="profile-main"><div class="profile-numbers"><span><strong>${fmt(profile.followers)}</strong> abonnés</span><span><strong>${fmt(profile.plays)}</strong> écoutes</span><span><strong>${beats.length}</strong> productions</span></div>${profile.role==='Beatmaker'?`${sectionTitle('Productions','Catalogue public de ce beatmaker.')}${beatGrid(beats)}`:`${sectionTitle('Univers artistique','Collaborations, influences et projets publics.')}<div class="service-card"><h3>Direction artistique personnalisée</h3><p>${esc(profile.bio)}</p><div class="tags"><span>Collaboration</span><span>Réservation</span><span>Message privé</span></div></div>`}</section><aside class="panel"><h3>Identité du profil</h3><p class="muted">Cette page utilise les couleurs, effets, cadres, arrière-plan et icônes choisis par le membre.</p><div class="theme-swatches"><i style="background:${esc(t.accent||'#f6c90e')}"></i><i style="background:${esc(t.secondary||'#7c5cff')}"></i><i style="background:${esc(t.background||'#111217')}"></i></div><a class="btn profile-btn full" href="${state.user?'#/app/messages':'#/connexion'}">Contacter</a></aside></div></div>`;return state.user?appShell(profile.name,`${profile.role} · Profil public`,body):publicShell(body);}

async function directory(role){const profiles=await service.listProfiles(role,state.directoryQuery);const label=role==='Beatmaker'?'Beatmakers':'Artistes';const content=`<div class="stack"><section class="directory-hero"><div><span class="badge">Annuaire complet</span><h2>${label}</h2><p>Recherche un membre par nom, univers, bio ou localisation.</p></div><label class="search-box">${icon('search')}<input id="directory-search" value="${esc(state.directoryQuery)}" placeholder="Rechercher un ${role.toLowerCase()}…"></label></section><section>${sectionTitle(`${profiles.length} profil${profiles.length>1?'s':''}`,'Chaque page peut avoir ses propres couleurs, cadres, effets et médias.')}${profileGrid(profiles)}</section></div>`;return appShell(label,'Annuaire de la communauté',content);}

async function favorites(){const beats=await service.favorites(state.user);return appShell('Mes favoris','Productions sauvegardées',`<div class="stack"><section class="manage-hero"><div><span class="badge">Bibliothèque</span><h2>Retrouve tes sélections.</h2><p>Les favoris sont liés à ton compte et restent disponibles sur tous tes appareils.</p></div><a class="btn primary" href="#/app/explorer">Explorer</a></section><section>${beatGrid(beats)}</section></div>`);}
async function playlistsPage(){
 const playlists=await service.playlists(state.user);
 const cards=playlists.length
  ? `<div class="playlist-grid">${playlists.map((p,i)=>`<article class="playlist-card"><div class="playlist-cover cover-${['a','b','c','d'][i%4]}"><span class="cover-grid"></span><strong>${(p.beat_ids||p.playlist_items||[]).length}</strong><span>productions</span></div><h3>${esc(p.name)}</h3><p>Playlist privée de ${esc(state.user.name)}.</p><button class="btn subtle full" data-toast="Ouverture de la playlist">Ouvrir</button></article>`).join('')}</div>`
  : `<div class="empty-state"><span>${icon('library')}</span><strong>Aucune playlist</strong><p>Crée ta première collection.</p></div>`;
 const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Collections</span><h2>Organise les productions par projet.</h2><p>Albums, singles, références, artistes ou ambiances : crée tes propres listes.</p></div><button class="btn primary" data-open-playlist>${icon('plus')} Nouvelle playlist</button></section>${cards}</div>`;
 return appShell('Playlists','Organisation personnelle',body);
}

async function collaborationsPage(){const list=await service.collaborations(state.user);return appShell('Collaborations','Projets privés',`<div class="stack"><section class="collab-hero"><div><span class="badge">Studio collaboratif</span><h2>Versions, fichiers et décisions.</h2><p>Centralise les maquettes, commentaires horodatés, crédits et pourcentages de chaque morceau.</p></div></section><section class="collab-stats"><div class="collab-stat"><strong>${list.length}</strong><span>Projets</span></div><div class="collab-stat"><strong>${list.filter(x=>x.status==='À écouter').length}</strong><span>À écouter</span></div><div class="collab-stat"><strong>${list.filter(x=>x.status==='Modification demandée').length}</strong><span>Modifications</span></div><div class="collab-stat"><strong>${list.filter(x=>x.status==='Validé').length}</strong><span>Validés</span></div></section><section class="collab-grid">${list.map((c,i)=>`<article class="collab-card"><div class="collab-card-top"><span class="project-icon cover-${['a','b','c'][i%3]}">${icon('music')}</span><div><span class="status ${statusClass(c.status)}">${esc(c.status)}</span><h3>${esc(c.title)}</h3><p>Échéance : ${esc(c.deadline||'Non définie')}</p></div></div><div class="collab-progress"><span style="width:${Number(c.progress)||0}%"></span></div><div class="collab-stats"><span><strong>${Number(c.progress)||0}%</strong> progression</span><span><strong>${(c.files||[]).length}</strong> fichiers</span><span><strong>${(c.comments||c.collaboration_comments||[]).length}</strong> commentaires</span></div><a class="btn subtle full" href="#/app/collaborations/${c.id}">Ouvrir le projet</a></article>`).join('')}</section></div>`);}
async function collaborationDetail(id){const c=await service.getCollaboration(state.user,id);if(!c)return notFound();const beat=c.beat_id?await service.getBeat(c.beat_id):null;const profiles=await service.listProfiles();const members=(c.member_ids||c.collaboration_members?.map(m=>m.user_id)||[]).map(uid=>profileById(profiles,uid));const files=c.files||c.collaboration_files||[];const comments=c.comments||c.collaboration_comments||[];const credits=c.credits||c.collaboration_credits||[];const body=`<div class="stack"><a class="btn subtle small detail-back" href="#/app/collaborations">← Retour</a><section class="collab-detail-hero"><div class="detail-cover ${beat?.coverClass||'cover-a'}"><span class="cover-grid"></span></div><div><span class="status ${statusClass(c.status)}">${esc(c.status)}</span><h2>${esc(c.title)}</h2><p>${beat?`${esc(beat.title)} · ${esc(beat.producer_name)}`:'Projet musical privé'}</p><div class="members">${members.map(p=>profileAvatar(p,'small')).join('')}</div><div class="collab-progress large"><span style="width:${Number(c.progress)||0}%"></span></div><p>${Number(c.progress)||0}% terminé · Échéance ${esc(c.deadline||'non définie')}</p></div></section><div class="collab-detail-grid"><section class="panel">${sectionTitle('Fichiers et versions','Éléments partagés dans le projet.')}<div class="file-list">${files.length?files.map(f=>`<div class="quality-row"><span class="quality-dot">${icon('file')}</span><div><strong>${esc(f.name)}</strong><small>${esc(f.kind||'fichier')} · version ${esc(f.version||1)} · ${esc(f.size||'')}</small></div><button class="btn subtle small" data-toast="Téléchargement protégé">${icon('download')}</button></div>`).join(''):'<div class="empty-state"><strong>Aucun fichier</strong></div>'}</div></section><aside class="panel">${sectionTitle('Crédits et pourcentages','Répartition du projet.')}<div class="credits-list">${credits.map(cr=>{const p=profileById(profiles,cr.user_id);return `<div>${profileAvatar(p,'small')}<span><strong>${esc(p.name)}</strong><small>${esc(cr.role)}</small></span><b>${Number(cr.share)||0}%</b></div>`}).join('')}</div></aside></div><section class="panel">${sectionTitle('Commentaires horodatés','Retour précis sur l’audio.')}<div class="timeline-comments">${comments.map(cm=>{const p=profileById(profiles,cm.user_id);return `<div><button data-toast="Lecture à ${esc(cm.timecode)}">${esc(cm.timecode)}</button><span><strong>${esc(p.name)}</strong><p>${esc(cm.text)}</p></span></div>`}).join('')}</div><form class="chat-form" data-demo-comment><input required placeholder="Ajouter un commentaire à 0:00…"><button class="icon-btn">${icon('send')}</button></form></section></div>`;return appShell(c.title,'Collaboration privée',body);}

async function productions(){const beats=await service.listBeats(state.user.role==='Admin'?{}:{producer_id:state.user.id});const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Catalogue créateur</span><h2>Gère tes productions et leur disponibilité.</h2><p>Modifie les fichiers, l’apparence, les licences et passe une instru en Expiré lorsqu’elle est prise définitivement.</p></div><a class="btn primary" href="#/app/upload">${icon('upload')} Ajouter une production</a></section><section class="stats-grid">${statCard('music','Productions',String(beats.length),'Total')}${statCard('check','Publiées',String(beats.filter(b=>b.visibility==='Publié').length),'Disponibles')}${statCard('reserve','Réservées',String(beats.filter(b=>b.visibility==='Réservé').length),'En discussion')}${statCard('lock','Expirées',String(beats.filter(b=>b.visibility==='Expiré').length),'Prises définitivement')}</section>${beatGrid(beats,{owner:true})}</div>`;return appShell('Mes productions','Gestion du catalogue',body);}
function licenseRows(licenses){const list=licenses?.length?licenses:[{name:'MP3',price:39,description:'Fichier MP3 tagué.',terms:'Crédits obligatoires',active:true},{name:'WAV',price:59,description:'WAV haute qualité.',terms:'Crédits obligatoires',active:true},{name:'Premium + Stems',price:99,description:'WAV et pistes séparées.',terms:'Conditions personnalisables',active:true},{name:'Exclusive',price:null,description:'Discussion privée.',terms:'Conditions négociées',active:true}];return list.map((l,i)=>`<div class="license-edit-row" data-license-row><input name="license_name_${i}" value="${esc(l.name)}" required><input name="license_price_${i}" type="number" value="${l.price==null?'':Number(l.price)}" placeholder="Prix indicatif"><input name="license_description_${i}" value="${esc(l.description||'')}" placeholder="Description"><input name="license_terms_${i}" value="${esc(l.terms||'')}" placeholder="Conditions"><label><input name="license_active_${i}" type="checkbox" ${checked(l.active!==false)}> Active</label><button type="button" class="icon-btn" data-remove-license>×</button></div>`).join('');}
async function productionEditor(id=''){const beat=id?await service.getBeat(id):null;if(id&&!beat)return notFound();if(beat&&!canEditBeat(beat))return notFound();const producers=state.user.role==='Admin'?await service.listProfiles('Beatmaker'):[];const d=beat?.design||{};const body=`<div class="stack"><a class="btn subtle small detail-back" href="#/app/productions">← Retour aux productions</a><div class="editor-layout"><form id="production-form" class="editor-form"><input type="hidden" name="id" value="${esc(beat?.id||'')}"><section class="panel"><h2>${beat?'Modifier':'Ajouter'} une production</h2><p class="muted">Les gros fichiers seront envoyés à ton Google Drive par l’API Render.</p><div class="form-grid">${state.user.role==='Admin'?`<label>Propriétaire<select name="producer_id">${producers.map(p=>`<option value="${p.user_id}" ${selected(p.user_id,beat?.producer_id||state.user.id)}>${esc(p.name)}</option>`).join('')}</select></label>`:''}<label>Titre<input name="title" required value="${esc(beat?.title||'')}"></label><label>Visibilité<select name="visibility"><option ${selected('Brouillon',beat?.visibility)}>Brouillon</option><option ${selected('Publié',beat?.visibility||'Publié')}>Publié</option><option ${selected('Réservé',beat?.visibility)}>Réservé</option><option ${selected('Expiré',beat?.visibility)}>Expiré</option></select></label><label>BPM<input name="bpm" type="number" required value="${beat?.bpm||140}"></label><label>Tonalité<input name="key" required value="${esc(beat?.key||'C min')}"></label><label>Genre<input name="genre" required value="${esc(beat?.genre||'Trap')}"></label><label>Humeur<input name="mood" required value="${esc(beat?.mood||'Sombre')}"></label><label class="wide">Description<textarea name="description">${esc(beat?.description||'')}</textarea></label><label class="wide">Tags séparés par des virgules<input name="tags" value="${esc((beat?.tags||[]).join(', '))}"></label></div></section><section class="panel"><h3>Fichiers et Google Drive</h3><div class="upload-grid"><label class="upload-zone">${icon('upload')}<strong>Préécoute MP3</strong><small>Publique ou diffusée par lien signé</small><input type="file" name="preview" accept="audio/mpeg,audio/wav"></label><label class="upload-zone">${icon('file')}<strong>WAV original</strong><small>Fichier privé</small><input type="file" name="wav" accept="audio/wav"></label><label class="upload-zone">FLP / ALS / projet<small>Fichier de session privé</small><input type="file" name="project" accept=".flp,.als,.zip,.rar"></label><label class="upload-zone">Stems ZIP<small>Pistes séparées</small><input type="file" name="stems" accept=".zip,.rar"></label><label class="upload-zone">Couverture<small>JPG, PNG, WEBP</small><input type="file" name="cover" accept="image/*"></label></div><div id="upload-progress" class="upload-progress hidden"><span style="width:0"></span><strong>0%</strong></div>${beat?.files?.length?`<div class="file-list">${beat.files.map(f=>`<div class="quality-row"><span class="quality-dot">${icon('drive')}</span><div><strong>${esc(f.name)}</strong><small>${esc(f.kind)} · ${esc(f.size||'')}</small></div></div>`).join('')}</div>`:''}</section><section class="panel"><h3>Apparence de la production</h3><div class="form-grid"><label>Couleur principale<input name="accent" type="color" value="${esc(d.accent||'#f6c90e')}"></label><label>Couleur secondaire<input name="secondary" type="color" value="${esc(d.secondary||'#7c5cff')}"></label><label>Fond<input name="background" type="color" value="${esc(d.background||'#111217')}"></label><label>Police du titre<select name="titleFont"><option ${selected('Inter',d.titleFont)}>Inter</option><option ${selected('Space Grotesk',d.titleFont)}>Space Grotesk</option><option ${selected('Manrope',d.titleFont)}>Manrope</option><option ${selected('Montserrat',d.titleFont)}>Montserrat</option><option ${selected('Playfair Display',d.titleFont)}>Playfair Display</option><option ${selected('Bebas Neue',d.titleFont)}>Bebas Neue</option></select></label><label>Disposition<select name="infoLayout"><option value="bottom" ${selected('bottom',d.infoLayout)}>Bas</option><option value="glass" ${selected('glass',d.infoLayout)}>Verre</option><option value="side" ${selected('side',d.infoLayout)}>Latérale</option></select></label><label>Assombrissement <input name="overlay" type="range" min="0" max="90" value="${Number(d.overlay??45)}"></label><label>Arrondi <input name="cardRadius" type="range" min="8" max="40" value="${Number(d.cardRadius??24)}"></label><label>Icône Play personnalisée<input name="playIcon" type="file" accept="image/*,.svg"></label><label>Icône Pause personnalisée<input name="pauseIcon" type="file" accept="image/*,.svg"></label></div></section><section class="panel"><div class="section-title"><div><h3>Licences personnalisables</h3><p>Le prix reste indicatif : la décision finale se prend dans la conversation.</p></div><button id="add-license" type="button" class="btn subtle small">${icon('plus')} Ajouter</button></div><div id="license-editor" class="license-editor">${licenseRows(beat?.licenses)}</div></section><div class="editor-actions"><button class="btn primary" type="submit">Enregistrer la production</button>${beat?`<button class="btn danger-btn" type="button" data-delete-beat="${beat.id}">Supprimer</button>`:''}</div></form><aside class="editor-preview"><span class="eyebrow">Aperçu en direct</span><div id="beat-preview">${beatCard(beat||{id:'preview',title:'Titre de la production',producer_name:state.user.name,producer_slug:state.user.id,bpm:140,key:'C min',genre:'Trap',mood:'Sombre',plays:0,duration:'2:48',coverClass:'cover-a',visibility:'Brouillon',design:{accent:'#f6c90e',secondary:'#7c5cff',background:'#111217',titleFont:'Inter',infoLayout:'bottom',overlay:45,cardRadius:24}},{owner:true})}</div><div class="drive-info"><strong>${icon('drive')} Stockage Google Drive</strong><p>Préécoutes, WAV, projets et stems sont transférés via ton API privée Render. Les secrets Google ne sont jamais envoyés au navigateur.</p></div></aside></div></div>`;return appShell(beat?'Modifier la production':'Ajouter une production','Studio beatmaker',body);}

async function reservationsPage(){const [list,beats,profiles]=await Promise.all([service.listReservations(state.user),service.listBeats({}),service.listProfiles()]);const byBeat=id=>beats.find(b=>b.id===id)||{title:'Production supprimée',coverClass:'cover-a',producer_name:'—'};const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Réservations</span><h2>De la sélection à la décision finale.</h2><p>Chaque réservation est liée à une licence et à une conversation privée entre l’artiste et le beatmaker.</p></div></section><section class="reservation-list">${list.length?list.map(r=>{const b=byBeat(r.beat_id),artist=profileById(profiles,r.artist_id),maker=profileById(profiles,r.beatmaker_id);const canDecide=state.user.role==='Admin'||state.user.id===r.beatmaker_id;return `<article class="reservation-row"><span class="mini-cover ${b.coverClass||'cover-a'}"></span><div class="reservation-main"><strong>${esc(b.title)}</strong><span>${esc(artist.name)} → ${esc(maker.name)}</span><small>Licence ${esc(r.license_name)} · ${dateShort(r.created_at)}</small></div><span class="status ${statusClass(r.status)}">${esc(r.status)}</span><div class="reservation-actions"><a class="btn subtle small" href="#/app/messages/${r.conversation_id}">Conversation</a>${canDecide?`<button class="btn subtle small" data-reservation-status="${r.id}" data-status="Acceptée">Accepter</button><button class="btn subtle small" data-reservation-status="${r.id}" data-status="Refusée">Refuser</button>${r.status==='Acceptée'?`<button class="btn primary small" data-beat-status="${b.id}" data-status="Expiré">Marquer l’instru Expirée</button>`:''}`:''}</div></article>`}).join(''):'<div class="empty-state"><strong>Aucune réservation</strong><p>Les demandes apparaîtront ici.</p></div>'}</section></div>`;return appShell('Réservations','Suivi des demandes',body);}

async function messagesPage(id=''){const conversations=await service.listConversations(state.user);const currentId=id||conversations[0]?.id||'';state.conversationId=currentId;const current=currentId?await service.getConversation(state.user,currentId):null;const profiles=await service.listProfiles();const messageHtml=[];for(const m of current?.messages||[]){const sender=profileById(profiles,m.sender_id);if(m.type==='reservation'){const beat=await service.getBeat(m.payload?.beat_id||current.beat_id);messageHtml.push(`<div class="reservation-message"><span class="reservation-block-cover ${beat?.coverClass||'cover-a'}"></span><div><span class="eyebrow">Réservation automatique</span><h4>${esc(beat?.title||'Production')}</h4><p>${esc(beat?.producer_name||'Beatmaker')} · ${beat?.bpm||'—'} BPM · ${esc(beat?.key||'—')}</p><div class="chips"><span>${esc(m.payload?.license_name||'Licence')}</span><span>${esc(m.payload?.status||'En discussion')}</span></div>${m.payload?.note?`<p>${esc(m.payload.note)}</p>`:''}<a class="btn subtle small" href="#/beat/${beat?.slug||beat?.id||''}">Voir la production</a></div></div>`);}else if(m.type==='system')messageHtml.push(`<div class="system-message">${esc(m.text)}</div>`);else messageHtml.push(`<div class="message ${m.sender_id===state.user.id?'sent':''}"><small>${esc(sender.name)}</small>${esc(m.text)}</div>`);}const other=current?.members_profiles?.find(p=>p.user_id!==state.user.id)||current?.members_profiles?.[0];const body=`<div class="messages-layout"><aside class="conversation-list"><label class="search-box">${icon('search')}<input placeholder="Rechercher…"></label>${conversations.length?conversations.map(c=>{const p=c.members_profiles?.find(x=>x.user_id!==state.user.id)||c.members_profiles?.[0];return `<a class="conversation-item ${c.id===currentId?'active':''}" href="#/app/messages/${c.id}">${profileAvatar(p,'small')}<span><strong>${esc(c.title)}</strong><small>${esc(c.last_message?.text||'Nouvelle conversation')}</small></span><em>${timeAgo(c.updated_at)}</em></a>`}).join(''):'<div class="chat-empty">Aucune conversation</div>'}</aside><section class="chat">${current?`<header class="conversation-head">${profileAvatar(other,'small')}<div><h2>${esc(current.title)}</h2><span>Conversation privée · Réservation associée</span></div><a class="icon-btn" href="#/app/reservations">${icon('reserve')}</a></header><div class="chat-body">${messageHtml.join('')}</div><form id="chat-form" class="chat-form"><input name="message" required autocomplete="off" placeholder="Écrire un message…"><button class="icon-btn">${icon('send')}</button></form>`:`<div class="chat-empty"><span>${icon('message')}</span><strong>Sélectionne une conversation</strong><p>Les discussions sont créées automatiquement lors d’une réservation.</p></div>`}</section></div>`;return appShell('Messages','Conversations privées',body);}

async function announcements(){const list=await service.announcements();return appShell('Annonces','Demandes de productions',`<div class="stack"><section class="announcement-hero"><div><span class="badge">Mise en relation</span><h2>Décris la production que tu recherches.</h2><p>Genre, ambiance, BPM, tonalité, budget indicatif et date limite.</p></div>${isArtist()?`<button class="btn primary" data-open-announcement>${icon('plus')} Publier une annonce</button>`:''}</section><section class="announcement-grid">${list.map(a=>`<article class="announcement-card"><header><div><span class="avatar small">${initials(a.author)}</span><div><strong>${esc(a.author)}</strong><small>Artiste</small></div></div><span class="status">Ouverte</span></header><h3>${esc(a.title)}</h3><p>${esc(a.details)}</p><div class="announcement-meta"><span>${esc(a.budget)}</span><span>${esc(a.deadline)}</span></div><button class="btn subtle full" data-toast="Proposition envoyée">Proposer une production</button></article>`).join('')}</section></div>`);}
async function notificationsPage(){await service.markNotificationsRead(state.user);const list=state.notifications||[];const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Centre de notifications</span><h2>Réservations, messages et administration.</h2><p>Toutes les actions importantes liées à ton compte sont regroupées ici.</p></div></section><section class="panel notification-list">${list.length?list.map(n=>`<a class="notification-row ${n.read?'':'unread'}" href="${esc(n.link||'#/app')}"><span class="notification-icon">${icon(n.type==='reservation'?'reserve':'message')}</span><div><strong>${esc(n.title)}</strong><p>${esc(n.body)}</p><small>${timeAgo(n.created_at)}</small></div></a>`).join(''):'<div class="empty-state"><strong>Aucune notification</strong></div>'}</section></div>`;return appShell('Notifications','Activité du compte',body);}

async function profileCustomizer(){const p=await service.getProfile(state.user.id);if(!p)return notFound();const t=p.theme||{},s=p.socials||{};const body=`<div class="stack"><section class="manage-hero"><div><span class="badge">Personnalisation totale</span><h2>Construis une page impossible à confondre.</h2><p>Couleurs, cadres, effets, arrière-plan, images, réseaux et icônes de lecture.</p></div><a class="btn subtle" href="#/profile/${p.slug}">Voir mon profil public</a></section><div class="customizer-layout"><form id="profile-customizer" class="customizer-form"><section class="panel"><h3>Identité</h3><div class="form-grid"><label>Nom public<input name="name" required value="${esc(p.name)}"></label><label>Nom d’utilisateur<input name="username" value="${esc(p.username||'')}"></label><label>Localisation<input name="location" value="${esc(p.location||'')}"></label><label class="wide">Biographie<textarea name="bio">${esc(p.bio||'')}</textarea></label><label>Photo de profil<input name="avatar" type="file" accept="image/*"></label><label>Bannière<input name="banner" type="file" accept="image/*"></label><label class="wide">Image d’arrière-plan<input name="backgroundImage" type="file" accept="image/*"></label></div></section><section class="panel"><h3>Couleurs et effets</h3><div class="form-grid"><label>Couleur principale<input name="accent" type="color" value="${esc(t.accent||'#f6c90e')}"></label><label>Couleur secondaire<input name="secondary" type="color" value="${esc(t.secondary||'#7c5cff')}"></label><label>Fond<input name="background" type="color" value="${esc(t.background||'#111217')}"></label><label>Couleur du cadre<input name="cardBorder" type="color" value="${/^#[0-9a-f]{6}$/i.test(t.cardBorder||'')?t.cardBorder:'#3a3d46'}"></label><label>Effet<select name="profileEffect"><option value="particles" ${selected('particles',t.profileEffect)}>Particules</option><option value="waves" ${selected('waves',t.profileEffect)}>Vagues</option><option value="aurora" ${selected('aurora',t.profileEffect)}>Aurore</option><option value="stars" ${selected('stars',t.profileEffect)}>Étoiles</option><option value="embers" ${selected('embers',t.profileEffect)}>Braises</option><option value="spotlight" ${selected('spotlight',t.profileEffect)}>Projecteur</option><option value="grain" ${selected('grain',t.profileEffect)}>Grain</option><option value="bubbles" ${selected('bubbles',t.profileEffect)}>Bulles</option><option value="none" ${selected('none',t.profileEffect)}>Aucun</option></select></label><label>Cadre<select name="frameStyle"><option value="glass" ${selected('glass',t.frameStyle)}>Verre</option><option value="gold" ${selected('gold',t.frameStyle)}>Or</option><option value="neon" ${selected('neon',t.frameStyle)}>Lumineux</option><option value="soft" ${selected('soft',t.frameStyle)}>Doux</option><option value="minimal" ${selected('minimal',t.frameStyle)}>Minimal</option></select></label><label>Boutons<select name="buttonStyle"><option value="pill" ${selected('pill',t.buttonStyle)}>Arrondis</option><option value="soft" ${selected('soft',t.buttonStyle)}>Doux</option><option value="square" ${selected('square',t.buttonStyle)}>Carrés</option></select></label><label>Arrondi des cartes<input name="cardRadius" type="range" min="8" max="40" value="${Number(t.cardRadius||24)}"></label></div></section><section class="panel"><h3>Réseaux</h3><div class="form-grid"><label>Instagram<input name="instagram" value="${esc(s.instagram||'')}"></label><label>YouTube<input name="youtube" value="${esc(s.youtube||'')}"></label><label>TikTok<input name="tiktok" value="${esc(s.tiktok||'')}"></label><label>Twitch<input name="twitch" value="${esc(s.twitch||'')}"></label></div></section><section class="panel"><h3>Icônes personnalisées</h3><div class="form-grid"><label>Bouton Play<input name="customPlayIcon" type="file" accept="image/*,.svg"></label><label>Bouton Pause<input name="customPauseIcon" type="file" accept="image/*,.svg"></label></div><p class="muted">Pour les beatmakers, ces icônes peuvent être appliquées aux cartes et au lecteur de leurs productions.</p></section><button class="btn primary" type="submit">Enregistrer ma personnalisation</button></form><aside class="customizer-preview"><span class="eyebrow">Aperçu en direct</span><div id="profile-preview" class="profile-preview frame-${esc(t.frameStyle||'glass')} effect-${esc(t.profileEffect||'none')}" style="${themeVars(t)};${t.backgroundImage?`--profile-bg-image:url('${esc(t.backgroundImage)}')`:''}"><div class="preview-banner" style="${p.banner?`background-image:url('${esc(p.banner)}')`:''}"></div>${profileAvatar(p,'large')}<h2>${esc(p.name)}</h2><p>${esc(p.bio)}</p><button class="btn profile-btn">Bouton du profil</button></div></aside></div></div>`;return appShell('Personnalisation','Identité visuelle du profil',body);}

async function statsPage(){const [p,beats,reservations,conversations]=await Promise.all([service.getProfile(state.user.id),service.listBeats(isCreator()?{producer_id:state.user.id}:{publicOnly:true}),service.listReservations(state.user),service.listConversations(state.user)]);const bars=[38,52,46,69,61,82,73,91,77,96,88,100];const body=`<div class="stack"><section class="stats-grid">${statCard('headphones','Écoutes',fmt(p?.plays||0),'+12% ce mois')}${statCard('heart','Favoris',fmt(beats.reduce((s,b)=>s+(b.likes||0),0)),'Catalogue')}${statCard('reserve','Réservations',String(reservations.length),'Historique')}${statCard('message','Conversations',String(conversations.length),'Actives')}</section><div class="chart-layout"><section class="panel">${sectionTitle('Évolution des écoutes','Données de démonstration pour la première version.')}<div class="chart">${bars.map((h,i)=>`<i class="bar" style="height:${h}%"><span>${i+1}</span></i>`).join('')}</div></section><aside class="panel">${sectionTitle('Sources','Répartition estimée')}<div class="donut"><div><strong>68%</strong><span>Catalogue</span></div></div><div class="tags"><span>Catalogue 68%</span><span>Profils 18%</span><span>Partages 8%</span><span>Autres 6%</span></div></aside></div><section class="panel">${sectionTitle('Productions les plus actives','Classement actuel')}<div class="track-table">${beats.slice(0,8).map(b=>`<div class="track-row"><button class="track-cover ${b.coverClass||'cover-a'}" data-play="${b.id}">${playIcon(b)}</button><div><strong>${esc(b.title)}</strong><small>${esc(b.producer_name)}</small></div><span>${esc(b.genre)}</span><span>${b.bpm} BPM</span><span>${fmt(b.plays)} écoutes</span><span>${fmt(b.likes)} ♥</span></div>`).join('')}</div></section></div>`;return appShell('Statistiques','Performance et activité',body);}
async function settingsPage(){const p=await service.getProfile(state.user.id);const real=!window.DRSXData.isDemo();const body=`<div class="settings-layout"><aside class="settings-nav"><button class="active">Compte</button><button>Notifications</button><button>Confidentialité</button><button>Intégrations</button></aside><form id="settings-form" class="panel settings-form"><label>Nom<input value="${esc(p?.name||state.user.name)}"></label><label>E-mail<input type="email" value="${esc(state.user.email||'')}" disabled></label><label>Rôle<input value="${esc(state.user.role)}" disabled></label><label>Langue<input value="Français"></label><label class="wide">Description interne<textarea>${esc(p?.bio||'')}</textarea></label><label><input type="checkbox" checked> Notifications de réservation</label><label><input type="checkbox" checked> Notifications de message</label><button class="btn primary" type="submit">Enregistrer</button><section class="integration-status wide"><h3>État des intégrations</h3><p><strong>Mode :</strong> ${real?'Supabase + API Render':'Démonstration locale'}<br><strong>API :</strong> ${esc(window.DRSX_CONFIG?.apiBaseUrl||'Non configurée')}<br><strong>Drive :</strong> ${real?'Configuration côté Render':'Simulation locale'}</p>${window.DRSXData.isDemo()?'<button type="button" class="btn danger-btn" data-reset-demo>Réinitialiser la démonstration</button>':''}</section></form></div>`;return appShell('Paramètres','Compte et intégrations',body);}

async function adminPage(){const snap=await service.adminSnapshot();const users=snap.users||[],profiles=snap.profiles||[],beats=snap.beats||[],reservations=snap.reservations||[];const profileFor=id=>profiles.find(p=>p.user_id===id)||{};const body=`<div class="admin-dashboard"><section class="admin-welcome"><div><span class="badge">Administrateur principal</span><h2>Dzl 971 contrôle toute la plateforme.</h2><p>Gestion des comptes, profils, productions, réservations, licences, fichiers et qualité.</p></div><div class="hero-actions"><button class="btn primary" data-admin-add-user>${icon('plus')} Ajouter un utilisateur</button><a class="btn subtle" href="#/app/upload">Ajouter une production</a></div></section><section class="stats-grid">${statCard('users','Utilisateurs',String(users.length),'Tous rôles')}${statCard('music','Productions',String(beats.length),'Catalogue total')}${statCard('reserve','Réservations',String(reservations.length),'Toutes demandes')}${statCard('bell','Notifications',String((snap.notifications||[]).length),'Journal actif')}</section><div class="admin-grid"><section class="panel"><h3>Contrôle qualité simulé</h3>${[['Fichiers audio manquants',beats.filter(b=>!b.audio).length],['Pochettes absentes',beats.filter(b=>!b.coverImage).length],['BPM ou tonalité manquants',beats.filter(b=>!b.bpm||!b.key).length],['Productions réservées',beats.filter(b=>b.visibility==='Réservé').length]].map(([label,count])=>`<div class="quality-row"><span class="quality-dot">${icon(count?'bell':'check')}</span><div><strong>${esc(label)}</strong><small>${count?`${count} élément(s) à vérifier`:'Aucune anomalie détectée'}</small></div><span class="status ${count?'warning':'success'}">${count||'OK'}</span></div>`).join('')}</section><section class="panel"><h3>Accès total</h3><p class="muted">Le compte Admin peut créer, modifier ou supprimer tous les comptes et toutes les productions.</p><a class="btn primary full" href="#/app/productions">Gérer toutes les productions</a><a class="btn subtle full" href="#/app/reservations">Voir les réservations</a></section></div><section class="panel admin-section">${sectionTitle('Utilisateurs','Modification des rôles et suppression des comptes.')}<div class="admin-table"><div class="admin-table-head"><span>Utilisateur</span><span>E-mail</span><span>Rôle</span><span>Actions</span></div>${users.map(u=>{const p=profileFor(u.id);return `<div class="admin-table-row"><div>${profileAvatar(p.user_id?p:u,'small')}<span><strong>${esc(p.name||u.name||u.email||'Utilisateur')}</strong><small>${esc(p.username||'')}</small></span></div><span>${esc(u.email||'E-mail protégé')}</span><select data-admin-role="${u.id}">${['Artiste','Beatmaker','Producteur','Ingénieur du son','Manager','Admin'].map(r=>`<option ${selected(r,p.role||u.role)}>${r}</option>`).join('')}</select><div><a class="btn subtle small" href="#/profile/${p.slug||u.id}">${icon('edit')}</a>${u.id!==state.user.id?`<button class="btn danger-btn small" data-admin-delete-user="${u.id}">${icon('trash')}</button>`:''}</div></div>`}).join('')}</div></section><section class="panel admin-section">${sectionTitle('Productions','Modification et suppression globales.')}<div class="admin-table"><div class="admin-table-head beats"><span>Production</span><span>Beatmaker</span><span>Statut</span><span>Actions</span></div>${beats.map(b=>`<div class="admin-table-row beats"><div><span class="mini-cover ${b.coverClass||'cover-a'}"></span><strong>${esc(b.title)}</strong></div><span>${esc(b.producer_name)}</span><span class="status ${statusClass(b.visibility)}">${esc(b.visibility)}</span><div><a class="btn subtle small" href="#/app/production/${b.id}/edit">Modifier</a><button class="btn danger-btn small" data-delete-beat="${b.id}">Supprimer</button></div></div>`).join('')}</div></section></div>`;return appShell('Administration','Contrôle total Dzl 971',body);}


async function renderRoute(){const token=++state.routeToken;app.innerHTML=loading();try{state.user=state.user||service.currentUser?.()||null;if(state.user)state.notifications=await service.notifications(state.user);const raw=(location.hash||'#/').slice(1);const parts=raw.split('/').filter(Boolean);let html;
 if(raw==='/'||raw===''){const [beats,makers,artists]=await Promise.all([service.listBeats({publicOnly:true}),service.listProfiles('Beatmaker'),service.listProfiles('Artiste')]);html=landing(beats,makers,artists);}
 else if(raw==='/connexion')html=authPage('login');else if(raw==='/inscription')html=authPage('register');else if(raw==='/explorer')html=await explore(true);else if(parts[0]==='beat')html=await beatDetail(parts[1]);else if(parts[0]==='profile')html=await profilePage(parts[1]);
 else if(!state.user){location.hash='#/connexion';html=authPage('login');}
 else if(raw==='/app')html=await dashboard();else if(raw==='/app/explorer')html=await explore();else if(raw==='/app/beatmakers')html=await directory('Beatmaker');else if(raw==='/app/artistes')html=await directory('Artiste');else if(raw==='/app/favoris')html=await favorites();else if(raw==='/app/playlists')html=await playlistsPage();else if(raw==='/app/collaborations')html=await collaborationsPage();else if(parts[0]==='app'&&parts[1]==='collaborations'&&parts[2])html=await collaborationDetail(parts[2]);else if(raw==='/app/productions')html=isCreator()?await productions():await dashboard();else if(raw==='/app/upload')html=isCreator()?await productionEditor():await dashboard();else if(parts[0]==='app'&&parts[1]==='production'&&parts[3]==='edit')html=await productionEditor(parts[2]);else if(raw==='/app/reservations')html=await reservationsPage();else if(parts[0]==='app'&&parts[1]==='messages')html=await messagesPage(parts[2]||'');else if(raw==='/app/annonces')html=await announcements();else if(raw==='/app/notifications')html=await notificationsPage();else if(raw==='/app/personnalisation')html=await profileCustomizer();else if(raw==='/app/statistiques')html=await statsPage();else if(raw==='/app/parametres')html=await settingsPage();else if(raw==='/admin')html=state.user.role==='Admin'?await adminPage():await dashboard();else html=notFound();if(token!==state.routeToken)return;app.innerHTML=html;bind();bindMotionEffects();syncPlayer();window.scrollTo({top:0,behavior:'instant'});}catch(e){console.error(e);app.innerHTML=`<div class="empty-state full-page"><strong>Une erreur est survenue</strong><p>${esc(e.message)}</p><button class="btn primary" data-nav="/app">Réessayer</button></div>`;bind();}}
function route(){app.classList.remove('route-loading');void app.offsetWidth;app.classList.add('route-loading');const run=()=>renderRoute().finally(()=>setTimeout(()=>app.classList.remove('route-loading'),500));if(document.startViewTransition&&app.innerHTML&&!matchMedia('(prefers-reduced-motion: reduce)').matches)document.startViewTransition(run);else run();}

function playBeat(id){service.getBeat(id).then(b=>{if(!b)return;if(state.current?.id===id){if(audio.paused){audio.play().catch(()=>{});state.isPlaying=true;}else{audio.pause();state.isPlaying=false;}}else{state.current=b;audio.src=b.audio||b.preview_url||'';audio.play().catch(()=>toast('La préécoute distante nécessite la configuration Drive.','error'));state.isPlaying=true;}route();});}
function next(){service.listBeats({publicOnly:true}).then(bs=>{const i=state.current?bs.findIndex(x=>x.id===state.current.id):-1;if(bs.length)playBeat(bs[(i+1)%bs.length].id);});}
function prev(){service.listBeats({publicOnly:true}).then(bs=>{const i=state.current?bs.findIndex(x=>x.id===state.current.id):0;if(bs.length)playBeat(bs[(i-1+bs.length)%bs.length].id);});}
function syncPlayer(){if(!state.current)return;const p=document.getElementById('progress'),ct=document.getElementById('current-time'),dur=document.getElementById('duration'),vol=document.getElementById('volume');audio.ontimeupdate=()=>{if(p&&audio.duration)p.value=String(audio.currentTime/audio.duration*100);if(ct)ct.textContent=formatTime(audio.currentTime);if(dur&&audio.duration)dur.textContent=formatTime(audio.duration);};audio.onended=next;if(p)p.oninput=()=>{if(audio.duration)audio.currentTime=Number(p.value)/100*audio.duration;};if(vol)vol.oninput=()=>audio.volume=Number(vol.value);}
function formatTime(v){if(!Number.isFinite(v))return'0:00';return`${Math.floor(v/60)}:${String(Math.floor(v%60)).padStart(2,'0')}`;}
function fileDataUrl(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=reject;r.readAsDataURL(file);});}
function imageDataUrl(file,max=1400,quality=.84){if(!file)return Promise.resolve('');if(file.type==='image/svg+xml')return fileDataUrl(file);return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const scale=Math.min(1,max/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.width*scale));c.height=Math.max(1,Math.round(img.height*scale));c.getContext('2d').drawImage(img,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL(file.type==='image/png'?'image/png':'image/webp',quality));};img.onerror=e=>{URL.revokeObjectURL(url);reject(e)};img.src=url;});}
function collectLicenses(form){return [...form.querySelectorAll('[data-license-row]')].map(row=>{const get=p=>row.querySelector(`[name^="${p}"]`);return{name:get('license_name_')?.value||'Licence',price:get('license_price_')?.value?Number(get('license_price_').value):null,description:get('license_description_')?.value||'',terms:get('license_terms_')?.value||'',active:!!get('license_active_')?.checked,custom:true};});}

function bind(){document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=e=>{e.preventDefault();location.hash='#'+el.dataset.nav;});document.querySelectorAll('[data-play]').forEach(el=>el.onclick=e=>{e.preventDefault();e.stopPropagation();playBeat(el.dataset.play);});document.querySelectorAll('[data-toast]').forEach(el=>el.onclick=e=>{e.preventDefault();toast(el.dataset.toast);});document.querySelectorAll('[data-action="logout"]').forEach(el=>el.onclick=async()=>{await service.logout();state.user=null;audio.pause();location.hash='#/';});document.querySelectorAll('[data-player]').forEach(el=>el.onclick=()=>{const a=el.dataset.player;if(a==='toggle')state.current?playBeat(state.current.id):service.listBeats({publicOnly:true}).then(bs=>bs[0]&&playBeat(bs[0].id));if(a==='next')next();if(a==='prev')prev();});document.querySelectorAll('[data-genre]').forEach(el=>el.onclick=()=>{state.genre=el.dataset.genre;route();});const search=document.getElementById('beat-search');if(search)search.oninput=e=>{state.query=e.target.value;clearTimeout(search._t);search._t=setTimeout(route,180);};const ds=document.getElementById('directory-search');if(ds)ds.oninput=e=>{state.directoryQuery=e.target.value;clearTimeout(ds._t);ds._t=setTimeout(route,180);};
 document.querySelectorAll('[data-favorite]').forEach(el=>el.onclick=async e=>{e.preventDefault();if(!state.user){location.hash='#/connexion';return;}const added=await service.toggleFavorite(state.user,el.dataset.favorite);toast(added?'Ajouté aux favoris':'Retiré des favoris');});
 document.querySelectorAll('[data-reserve]').forEach(el=>el.onclick=async()=>{if(!state.user){location.hash='#/connexion';return;}const beat=await service.getBeat(el.dataset.reserve);state.modal={type:'reserve',beat,license:el.dataset.license};route();});document.querySelectorAll('[data-close-modal]').forEach(el=>el.onclick=()=>{state.modal=null;route();});const confirm=document.querySelector('[data-confirm-reservation]');if(confirm)confirm.onclick=async()=>{confirm.disabled=true;confirm.textContent='Création de la conversation…';try{const result=await service.reserveBeat(state.user,state.modal.beat.id,state.modal.license,document.getElementById('reservation-note')?.value||'');state.modal=null;toast('Réservation envoyée au beatmaker');location.hash=`#/app/messages/${result.conversation?.id||result.conversation_id}`;}catch(e){toast(e.message,'error');confirm.disabled=false;}};
 const lf=document.getElementById('login-form');if(lf)lf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(lf);try{state.user=await service.login(fd.get('email'),fd.get('password'));activateSubscription();location.hash=state.user.role==='Admin'?'#/admin':'#/app';}catch(err){const box=document.getElementById('login-error');box.textContent=err.message;box.classList.remove('hidden');}};const rf=document.getElementById('register-form');if(rf)rf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(rf);try{const created=await service.register({name:fd.get('name'),email:fd.get('email'),password:fd.get('password'),role:fd.get('role')});if(!window.DRSXData.isDemo()&&!created.access_token){state.user=null;toast('Compte créé. Confirme ton e-mail puis connecte-toi.');location.hash='#/connexion';return;}state.user=created;activateSubscription();toast('Compte créé');location.hash='#/app/personnalisation';}catch(err){toast(err.message,'error');}};
 const cf=document.getElementById('chat-form');if(cf)cf.onsubmit=async e=>{e.preventDefault();const text=new FormData(cf).get('message');await service.sendMessage(state.user,state.conversationId,text);cf.reset();route();};document.querySelectorAll('[data-reservation-status]').forEach(el=>el.onclick=async()=>{await service.updateReservation(state.user,el.dataset.reservationStatus,el.dataset.status);toast(`Réservation ${el.dataset.status.toLowerCase()}`);route();});document.querySelectorAll('[data-beat-status]').forEach(el=>el.onclick=async()=>{const b=await service.getBeat(el.dataset.beatStatus);await service.saveBeat(state.user,{...b,visibility:el.dataset.status});toast(`Production passée en ${el.dataset.status}`);route();});
 document.querySelector('[data-open-playlist]')?.addEventListener('click',()=>{state.modal={type:'playlist'};route();});const plf=document.getElementById('playlist-form');if(plf)plf.onsubmit=async e=>{e.preventDefault();await service.savePlaylist(state.user,new FormData(plf).get('name'));state.modal=null;toast('Playlist créée');route();};document.querySelector('[data-open-announcement]')?.addEventListener('click',()=>{state.modal={type:'announcement'};route();});const af=document.getElementById('announcement-form');if(af)af.onsubmit=async e=>{e.preventDefault();const fd=new FormData(af);await service.saveAnnouncement(state.user,Object.fromEntries(fd));state.modal=null;toast('Annonce publiée');route();};
 const addLicense=document.getElementById('add-license');if(addLicense)addLicense.onclick=()=>{const ed=document.getElementById('license-editor');const i=ed.querySelectorAll('[data-license-row]').length;ed.insertAdjacentHTML('beforeend',`<div class="license-edit-row" data-license-row><input name="license_name_${i}" value="Licence personnalisée"><input name="license_price_${i}" type="number" placeholder="Prix indicatif"><input name="license_description_${i}" placeholder="Description"><input name="license_terms_${i}" placeholder="Conditions"><label><input name="license_active_${i}" type="checkbox" checked> Active</label><button type="button" class="icon-btn" data-remove-license>×</button></div>`);bindRemoveLicenses();};bindRemoveLicenses();
 const pf=document.getElementById('production-form');if(pf){pf.oninput=()=>updateBeatPreview(pf);pf.onsubmit=e=>handleProductionSubmit(e,pf);}
 document.querySelectorAll('[data-delete-beat]').forEach(el=>el.onclick=async()=>{if(confirm('Supprimer définitivement cette production ?')){await service.deleteBeat(state.user,el.dataset.deleteBeat);toast('Production supprimée');location.hash=state.user.role==='Admin'?'#/admin':'#/app/productions';}});
 const pc=document.getElementById('profile-customizer');if(pc){pc.oninput=()=>updateProfilePreview(pc);pc.onsubmit=e=>handleProfileSubmit(e,pc);}
 document.querySelector('[data-demo-comment]')?.addEventListener('submit',e=>{e.preventDefault();toast('Commentaire horodaté ajouté');e.target.reset();});document.getElementById('settings-form')?.addEventListener('submit',e=>{e.preventDefault();toast('Paramètres enregistrés');});document.querySelector('[data-admin-add-user]')?.addEventListener('click',()=>{state.modal={type:'addUser'};route();});const auf=document.getElementById('admin-add-user-form');if(auf)auf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(auf);await service.adminCreateUser(Object.fromEntries(fd));state.modal=null;toast('Utilisateur ajouté');route();};document.querySelectorAll('[data-admin-role]').forEach(el=>el.onchange=async()=>{await service.adminSetUserRole(el.dataset.adminRole,el.value);toast('Rôle modifié');});document.querySelectorAll('[data-admin-delete-user]').forEach(el=>el.onclick=async()=>{if(confirm('Supprimer ce compte et ses contenus ?')){await service.adminDeleteUser(el.dataset.adminDeleteUser);toast('Utilisateur supprimé');route();}});document.querySelector('[data-reset-demo]')?.addEventListener('click',async()=>{if(confirm('Réinitialiser toutes les données de démonstration ?')){await service.resetDemo();state.user=null;location.hash='#/connexion';}});}
function bindRemoveLicenses(){document.querySelectorAll('[data-remove-license]').forEach(el=>el.onclick=()=>el.closest('[data-license-row]')?.remove());}
function updateBeatPreview(form){const fd=new FormData(form);const current={id:'preview',title:fd.get('title')||'Titre de la production',producer_name:state.user.name,producer_slug:state.user.id,bpm:fd.get('bpm')||140,key:fd.get('key')||'C min',genre:fd.get('genre')||'Trap',mood:fd.get('mood')||'Sombre',plays:0,likes:0,duration:'2:48',coverClass:'cover-a',visibility:fd.get('visibility')||'Brouillon',tags:[],design:{accent:fd.get('accent'),secondary:fd.get('secondary'),background:fd.get('background'),titleFont:fd.get('titleFont'),infoLayout:fd.get('infoLayout'),overlay:Number(fd.get('overlay')),cardRadius:Number(fd.get('cardRadius'))}};const target=document.getElementById('beat-preview');if(target){target.innerHTML=beatCard(current,{owner:true});bind();}}
async function handleProductionSubmit(e,form){e.preventDefault();const btn=form.querySelector('button[type="submit"]');btn.disabled=true;btn.textContent='Enregistrement…';try{const fd=new FormData(form);let old=fd.get('id')?await service.getBeat(fd.get('id')):null;const design={...(old?.design||{}),accent:fd.get('accent'),secondary:fd.get('secondary'),background:fd.get('background'),titleFont:fd.get('titleFont'),infoLayout:fd.get('infoLayout'),overlay:Number(fd.get('overlay')),cardRadius:Number(fd.get('cardRadius'))};const playFile=form.elements.playIcon.files[0],pauseFile=form.elements.pauseIcon.files[0];if(playFile)design.customPlayIcon=await fileDataUrl(playFile);if(pauseFile)design.customPauseIcon=await fileDataUrl(pauseFile);let beat=await service.saveBeat(state.user,{...(old||{}),id:old?.id,producer_id:fd.get('producer_id')||old?.producer_id||state.user.id,title:fd.get('title'),visibility:fd.get('visibility'),bpm:Number(fd.get('bpm')),key:fd.get('key'),genre:fd.get('genre'),mood:fd.get('mood'),description:fd.get('description'),tags:String(fd.get('tags')).split(',').map(x=>x.trim()).filter(Boolean),design,licenses:collectLicenses(form)});const files=[['preview','preview'],['wav','wav'],['project','project'],['stems','stems'],['cover','cover']];const uploaded=[...(old?.files||[])];for(const [field,kind] of files){const file=form.elements[field].files[0];if(!file)continue;if(window.DRSXData.isDemo()&&kind==='cover'){beat.coverImage=await imageDataUrl(file);continue;}const progress=document.getElementById('upload-progress');progress.classList.remove('hidden');const result=await service.uploadFile(state.user,file,{kind,beatId:beat.id},p=>{progress.querySelector('span').style.width=p+'%';progress.querySelector('strong').textContent=p+'%';});if(kind==='preview'&&result.stream_url&&!window.DRSXData.isDemo())beat.audio=result.stream_url;if(kind==='cover'&&result.stream_url)beat.coverImage=result.stream_url;else uploaded.push({name:file.name,kind,size:`${(file.size/1024/1024).toFixed(1)} Mo`,drive_id:result.id,stream_url:result.stream_url||''});}beat=await service.saveBeat(state.user,{...beat,files:uploaded});toast('Production enregistrée');location.hash='#/app/productions';}catch(err){console.error(err);toast(err.message,'error');btn.disabled=false;btn.textContent='Enregistrer la production';}}
function updateProfilePreview(form){const fd=new FormData(form),box=document.getElementById('profile-preview');if(!box)return;box.style.setProperty('--profile-accent',fd.get('accent'));box.style.setProperty('--profile-secondary',fd.get('secondary'));box.style.setProperty('--profile-bg',fd.get('background'));box.style.setProperty('--profile-radius',fd.get('cardRadius')+'px');box.className=`profile-preview frame-${fd.get('frameStyle')} effect-${fd.get('profileEffect')}`;box.querySelector('h2').textContent=fd.get('name')||'Ton nom';box.querySelector('p').textContent=fd.get('bio')||'Ta biographie';}
async function handleProfileSubmit(e,form){e.preventDefault();const fd=new FormData(form),old=await service.getProfile(state.user.id),theme={...(old.theme||{}),accent:fd.get('accent'),secondary:fd.get('secondary'),background:fd.get('background'),profileEffect:fd.get('profileEffect'),frameStyle:fd.get('frameStyle'),buttonStyle:fd.get('buttonStyle'),cardRadius:Number(fd.get('cardRadius')),cardBorder:fd.get('cardBorder')};const imgFields=['avatar','banner','backgroundImage','customPlayIcon','customPauseIcon'];const values={};for(const f of imgFields){const file=form.elements[f]?.files[0];if(!file)continue;if(window.DRSXData.isDemo())values[f]=await imageDataUrl(file,f.includes('Icon')?320:1600,.86);else{const uploaded=await service.uploadFile(state.user,file,{kind:'cover',beatId:`profile-${state.user.id}`},p=>{});values[f]=uploaded.stream_url;}}if(values.backgroundImage)theme.backgroundImage=values.backgroundImage;if(values.customPlayIcon)theme.customPlayIcon=values.customPlayIcon;if(values.customPauseIcon)theme.customPauseIcon=values.customPauseIcon;const p=await service.saveProfile(state.user.id,{name:fd.get('name'),username:fd.get('username'),location:fd.get('location'),bio:fd.get('bio'),avatar:values.avatar||old.avatar,banner:values.banner||old.banner,socials:{instagram:fd.get('instagram'),youtube:fd.get('youtube'),tiktok:fd.get('tiktok'),twitch:fd.get('twitch')},theme});if(isCreator()&&(values.customPlayIcon||values.customPauseIcon)){const bs=await service.listBeats({producer_id:state.user.id});for(const b of bs)await service.saveBeat(state.user,{...b,design:{...b.design,customPlayIcon:values.customPlayIcon||b.design?.customPlayIcon,customPauseIcon:values.customPauseIcon||b.design?.customPauseIcon}});}state.user.name=p.name;toast('Profil entièrement personnalisé');location.hash=`#/profile/${p.slug}`;}
function bindMotionEffects(){document.querySelectorAll('.beat-card,.feature-card,.creator-card,.license-card,.stat-card,.announcement-card,.reservation-row').forEach(card=>{card.onpointermove=e=>{const r=card.getBoundingClientRect();card.style.setProperty('--mx',`${(e.clientX-r.left)/r.width*100}%`);card.style.setProperty('--my',`${(e.clientY-r.top)/r.height*100}%`);};card.onpointerleave=()=>{card.style.removeProperty('--mx');card.style.removeProperty('--my');};});}

window.addEventListener('hashchange',route);audio.volume=.75;audio.onplay=()=>state.isPlaying=true;audio.onpause=()=>state.isPlaying=false;(async()=>{if(!window.DRSXData.isDemo()&&(window.DRSX_CONFIG?.apiBaseUrl||window.DRSX_CONFIG?.driveWorkerUrl)){fetch(`${String(window.DRSX_CONFIG.apiBaseUrl||window.DRSX_CONFIG.driveWorkerUrl).replace(/\/$/,'')}/health`,{cache:'no-store'}).catch(()=>{});}try{state.user=await service.init();}catch(e){console.warn('Mode distant indisponible, vérifie config.js',e);toast('Configuration distante incomplète : utilise le mode démo ou renseigne config.js.','error');}activateSubscription();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});route();})();
})();
